1	"use client";
2	
3	import { useEffect, useMemo, useRef, useState } from "react";
4	import { useRouter } from "next/navigation";
5	import { lookupMemberByCode } from "./ticket-actions";
6	import { addMember, type AddMemberState } from "../(dashboard)/members/actions";
7	import AddMemberForm from "../(dashboard)/members/add-member-form";
8	
9	export type SelectedMember = { id: string; name: string; memberCode: string; validUntil: string };
10	
11	export type FullMember = {
12	  id: string;
13	  name: string;
14	  phone: string | null;
15	  memberCode: string;
16	  validFrom: string;
17	  validUntil: string;
18	};
19	
20	export default function MemberPanel({
21	  businessId,
22	  members,
23	  member,
24	  onSelect,
25	  onRelease,
26	}: {
27	  businessId: string;
28	  members: FullMember[];
29	  member: SelectedMember | null;
30	  onSelect: (member: SelectedMember) => void;
31	  onRelease: () => void;
32	}) {
33	  const router = useRouter();
34	  const [memberCode, setMemberCode] = useState("");
35	  const [memberError, setMemberError] = useState<string | null>(null);
36	  const [memberBusy, setMemberBusy] = useState(false);
37	  const codeInputRef = useRef<HTMLInputElement>(null);
38	
39	  const [listOpen, setListOpen] = useState(false);
40	  const [search, setSearch] = useState("");
41	  const [addOpen, setAddOpen] = useState(false);
42	
43	  useEffect(() => {
44	    if (!member) {
45	      codeInputRef.current?.focus();
46	    }
47	  }, [member]);
48	
49	  const filteredMembers = useMemo(() => {
50	    const q = search.trim().toLowerCase();
51	    if (!q) return members;
52	    return members.filter(
53	      (m) =>
54	        m.name.toLowerCase().includes(q) ||
55	        m.memberCode.toLowerCase().includes(q) ||
56	        m.phone?.toLowerCase().includes(q),
57	    );
58	  }, [search, members]);
59	
60	  async function handleLookup() {
61	    setMemberError(null);
62	    setMemberBusy(true);
63	    const result = await lookupMemberByCode(businessId, memberCode);
64	    setMemberBusy(false);
65	    if (!result.success) {
66	      setMemberError(result.error);
67	      return;
68	    }
69	    onSelect(result.member);
70	    setMemberCode("");
71	  }
72	
73	  async function handleAddMember(state: AddMemberState, formData: FormData) {
74	    const result = await addMember(businessId, state, formData);
75	    if (!result.error) {
76	      router.refresh();
77	    }
78	    return result;
79	  }
80	
81	  if (member) {
82	    return (
83	      <div className="mb-4 rounded-xl border border-zinc-200 bg-white p-3.5">
84	        <p className="mb-2 text-xs font-medium text-zinc-600">Member</p>
85	        <div className="flex items-center justify-between rounded-lg bg-brand-50 px-3 py-2">
86	          <div>
87	            <p className="text-sm font-semibold text-brand-700">{member.name}</p>
88	            <p className="text-[11px] text-brand-600">
89	              {member.memberCode} · berlaku s/d{" "}
90	              {new Date(member.validUntil).toLocaleDateString("id-ID")}
91	            </p>
92	          </div>
93	          <button
94	            onClick={onRelease}
95	            className="text-xs font-medium text-brand-700 hover:underline"
96	          >
97	            Lepas
98	          </button>
99	        </div>
100	      </div>
101	    );
102	  }
