    .eq("business_id", businessId)
    .single();

  if (!business || !member) {
    notFound();
  }

  return (
    <div className="w-full max-w-xs print:max-w-none">
      <div className="print:hidden">
        <PrintButton businessId={businessId} memberId={memberId} />
