1	import Link from "next/link";
2	import { notFound } from "next/navigation";
3	import { createClient } from "@/lib/supabase/server";
4	import {
5	  PERIOD_DESCRIPTIONS,
6	  PERIOD_LABELS,
7	  REPORT_TIMEZONE,
8	  getPeriodRange,
9	  parsePeriod,
10	  type Period,
11	} from "./period";
12	
13	const DONUT_PALETTE = ["#0f766e", "#34d399", "#fcd34d", "#a78bfa", "#fb923c", "#60a5fa", "#f87171"];
14	const CATEGORY_PALETTE = ["#0f766e", "#10b981", "#34d399", "#6ee7b7", "#a7f3d0", "#d1fae5"];
15	const MEDALS = ["🥇", "🥈", "🥉"];
16	
17	function formatRupiah(value: number) {
18	  const sign = value < 0 ? "-" : "";
19	  return `${sign}Rp${Math.round(Math.abs(value)).toLocaleString("id-ID")}`;
20	}
21	
22	function formatDateTime(iso: string) {
23	  return new Date(iso).toLocaleString("id-ID", {
24	    day: "2-digit",
25	    month: "short",
26	    hour: "2-digit",
27	    minute: "2-digit",
28	    timeZone: REPORT_TIMEZONE,
29	  });
30	}
31	
32	const hourFormatter = new Intl.DateTimeFormat("en-US", {
33	  hour: "numeric",
34	  hourCycle: "h23",
35	  timeZone: REPORT_TIMEZONE,
36	});
37	
38	function wibHour(iso: string) {
39	  return Number(hourFormatter.format(new Date(iso)));
40	}
41	
42	function buildDonutSegments(entries: [string, number][], total: number) {
43	  const R = 28;
44	  const cx = 40;
45	  const cy = 40;
46	  // Satu metode = lingkaran penuh; path arc 360° akan degenerate (titik awal == akhir).
47	  if (entries.length === 1) {
48	    return [{ d: null, color: DONUT_PALETTE[0] }];
49	  }
50	  let angle = -Math.PI / 2;
51	  return entries.map(([, val], i) => {
52	    const sweep = (val / total) * 2 * Math.PI;
53	    const x1 = cx + R * Math.cos(angle);
54	    const y1 = cy + R * Math.sin(angle);
55	    const x2 = cx + R * Math.cos(angle + sweep);
56	    const y2 = cy + R * Math.sin(angle + sweep);
57	    const large = sweep > Math.PI ? 1 : 0;
58	    angle += sweep;
59	    return {
60	      d: `M${cx},${cy} L${x1},${y1} A${R},${R} 0 ${large},1 ${x2},${y2} Z`,
61	      color: DONUT_PALETTE[i % DONUT_PALETTE.length],
62	    };
63	  });
64	}
65	
66	export default async function ReportsPage({
67	  params,
68	  searchParams,
69	}: {
70	  params: Promise<{ businessId: string }>;
71	  searchParams: Promise<{ period?: string; from?: string; to?: string }>;
72	}) {
73	  const { businessId } = await params;
74	  const { period: periodParam, from, to } = await searchParams;
75	  const period = parsePeriod(periodParam);
76	  const { fromIso, toIsoExclusive } = getPeriodRange(period, from, to);
77	
78	  const supabase = await createClient();
79	
80	  const { data: business } = await supabase
81	    .from("businesses")
82	    .select("id, name")
83	    .eq("id", businessId)
84	    .single();
85	
86	  if (!business) {
87	    notFound();
88	  }
89	
90	  let txQuery = supabase
91	    .from("transactions")
92	    .select(
93	      "id, invoice_number, date, subtotal, total, total_cost, gross_profit, is_split, voided, transaction_items(product_id, name, category, price, qty), transaction_payments(method, amount)",
94	    )
95	    .eq("business_id", businessId)
96	    .order("date", { ascending: false });
97	  if (fromIso) txQuery = txQuery.gte("date", fromIso);
98	  if (toIsoExclusive) txQuery = txQuery.lt("date", toIsoExclusive);
99	  const { data: transactions } = await txQuery;
100	
101	  const txList = transactions ?? [];
102	  const validTx = txList.filter((t) => !t.voided);
103	  const voidCount = txList.length - validTx.length;
104	
105	  // ── KPI utama ──
106	  const revenue = validTx.reduce((s, t) => s + Number(t.total), 0);
107	  const count = validTx.length;
108	  const avg = count > 0 ? Math.round(revenue / count) : 0;
109	  const totalItems = validTx.reduce(
110	    (s, t) => s + t.transaction_items.reduce((a, i) => a + Number(i.qty), 0),
111	    0,
112	  );
113	
114	  // ── Laba kotor & margin — hanya dari transaksi yang punya data modal (total_cost > 0),
115	  // supaya produk tanpa harga modal tidak dihitung margin 100% dan menyesatkan. ──
116	  const txWithCost = validTx.filter((t) => Number(t.total_cost) > 0);
117	  const grossProfit = txWithCost.reduce((s, t) => s + Number(t.gross_profit), 0);
118	  const revenueWithCost = txWithCost.reduce((s, t) => s + Number(t.subtotal), 0);
119	  const avgMargin =
120	    revenueWithCost > 0 ? Math.round((grossProfit / revenueWithCost) * 100) : null;
121	  const missingCostCount = validTx.length - txWithCost.length;
122	
123	  // ── Tunai vs non-tunai ──
124	  let cashRev = 0;
125	  let nonCashRev = 0;
126	  for (const t of validTx) {
127	    for (const p of t.transaction_payments) {
128	      if (p.method === "Tunai") cashRev += Number(p.amount);
129	      else nonCashRev += Number(p.amount);
130	    }
131	  }
132	
133	  // ── Penjualan per jam (WIB) ──
134	  const hourly = Array<number>(24).fill(0);
135	  for (const t of validTx) {
136	    hourly[wibHour(t.date)] += Number(t.total);
137	  }
138	  const hourlyMax = Math.max(...hourly, 1);
139	  const currentHour = wibHour(new Date().toISOString());
140	
141	  // ── Metode pembayaran ──
142	  const byMethod = new Map<string, number>();
143	  for (const t of validTx) {
144	    for (const p of t.transaction_payments) {
145	      byMethod.set(p.method, (byMethod.get(p.method) ?? 0) + Number(p.amount));
146	    }
147	  }
148	  const methodEntries = Array.from(byMethod.entries()).sort((a, b) => b[1] - a[1]);
149	  const methodTotal = methodEntries.reduce((s, [, v]) => s + v, 0);
150	  const donutSegments = methodTotal > 0 ? buildDonutSegments(methodEntries, methodTotal) : [];
151	
152	  // ── Penjualan per kategori ──
153	  const byCategory = new Map<string, number>();
154	  for (const t of validTx) {
155	    for (const i of t.transaction_items) {
156	      const cat = i.category ?? "Lainnya";
157	      byCategory.set(cat, (byCategory.get(cat) ?? 0) + Number(i.price) * Number(i.qty));
158	    }
159	  }
160	  const categoryEntries = Array.from(byCategory.entries()).sort((a, b) => b[1] - a[1]);
161	  const categoryMax = categoryEntries[0]?.[1] ?? 1;
162	
163	  // ── Menu terlaris ──
164	  const menuSales = new Map<
165	    string,
166	    { name: string; productId: string | null; qty: number; sales: number }
167	  >();
168	  for (const t of validTx) {
169	    for (const i of t.transaction_items) {
170	      const entry = menuSales.get(i.name) ?? {
171	        name: i.name,
172	        productId: i.product_id,
173	        qty: 0,
174	        sales: 0,
175	      };
176	      entry.qty += Number(i.qty);
177	      entry.sales += Number(i.price) * Number(i.qty);
178	      menuSales.set(i.name, entry);
179	    }
180	  }
181	  const topMenus = Array.from(menuSales.values())
182	    .sort((a, b) => b.sales - a.sales)
183	    .slice(0, 8);
184	  const topMax = topMenus[0]?.sales ?? 1;
185	
186	  const productIds = topMenus.map((m) => m.productId).filter((id): id is string => id !== null);
187	  const emojiMap = new Map<string, string>();
188	  if (productIds.length > 0) {
189	    const { data: products } = await supabase
190	      .from("products")
191	      .select("id, emoji")
192	      .in("id", productIds);
193	    for (const p of products ?? []) {
194	      if (p.emoji) emojiMap.set(p.id, p.emoji);
195	    }
196	  }
197	
198	  const periodQuery =
199	    period === "custom"
200	      ? `period=custom${from ? `&from=${from}` : ""}${to ? `&to=${to}` : ""}`
201	      : `period=${period}`;
202	
203	  return (
204	    <div className="w-full max-w-3xl">
205	        <div className="flex flex-wrap items-center justify-between gap-2">
206	          <div>
207	            <h1 className="text-lg font-bold text-zinc-900">Laporan — {business.name}</h1>
208	            <p className="mt-0.5 text-xs text-zinc-500">{PERIOD_DESCRIPTIONS[period]}</p>
209	          </div>
210	          <div className="flex flex-wrap gap-1.5">
211	            {(["today", "week", "month", "all", "custom"] as Period[]).map((p) => (
212	              <Link
213	                key={p}
214	                href={`/business/${businessId}/reports?period=${p}`}
215	                className={`rounded-full px-3 py-1 text-xs font-medium transition-colors ${
216	                  p === period
217	                    ? "bg-brand-600 text-white"
218	                    : "bg-white text-zinc-600 hover:bg-zinc-100"
219	                }`}
220	              >
221	                {PERIOD_LABELS[p]}
222	              </Link>
223	            ))}
224	          </div>
225	        </div>
226	
227	        {period === "custom" && (
228	          <form
229	            method="get"
230	            className="mt-4 flex flex-wrap items-end gap-3 rounded-2xl border border-zinc-200 bg-white p-4"
231	          >
232	            <input type="hidden" name="period" value="custom" />
233	            <label className="text-xs font-medium text-zinc-600">
234	              Dari
235	              <input
236	                type="date"
237	                name="from"
238	                defaultValue={from}
239	                className="mt-1 block rounded-lg border border-zinc-200 px-2 py-1.5 text-sm"
240	              />
241	            </label>
242	            <label className="text-xs font-medium text-zinc-600">
243	              Sampai
244	              <input
245	                type="date"
246	                name="to"
247	                defaultValue={to}
248	                className="mt-1 block rounded-lg border border-zinc-200 px-2 py-1.5 text-sm"
249	              />
250	            </label>
251	            <button
252	              type="submit"
253	              className="rounded-lg bg-brand-600 px-4 py-2 text-xs font-semibold text-white hover:bg-brand-700"
254	            >
255	              Terapkan
256	            </button>
257	          </form>
258	        )}
259	
260	        {/* KPI utama */}
261	        <div className="mt-6 grid grid-cols-2 gap-3">
262	          <div className="col-span-2 rounded-2xl bg-brand-700 p-5">
263	            <p className="mb-1.5 text-[10.5px] font-semibold uppercase text-brand-200">
264	              Total Pendapatan
265	            </p>
266	            <p className="text-3xl font-bold text-white">{formatRupiah(revenue)}</p>
267	            <p className="mt-2 inline-block rounded-full bg-white/15 px-2.5 py-1 text-[11px] font-semibold text-white">
268	              {count > 0 ? `↑ ${count} transaksi` : "— Belum ada transaksi"}
269	            </p>
270	          </div>
271	          <div className="rounded-2xl border border-zinc-200 bg-white p-4">
272	            <p className="mb-1.5 text-[10.5px] font-semibold uppercase text-zinc-400">Transaksi</p>
273	            <p className="text-2xl font-bold text-zinc-900">{count}</p>
274	            <p className="mt-1 text-[11px] text-zinc-400">
275	              sukses · <span className="text-red-400">{voidCount} void</span>
276	            </p>
277	          </div>
278	          <div className="rounded-2xl border border-zinc-200 bg-white p-4">
279	            <p className="mb-1.5 text-[10.5px] font-semibold uppercase text-zinc-400">
280	              Rata-rata Bill
281	            </p>
282	            <p className="text-2xl font-bold text-zinc-900">{formatRupiah(avg)}</p>
283	            <p className="mt-1 text-[11px] text-zinc-400">per transaksi</p>
284	          </div>
285	        </div>
286	
287	        {/* Laba kotor (HPP) */}
288	        <div className="mt-3 grid grid-cols-2 gap-3">
289	          <div className="rounded-2xl border border-brand-200 bg-brand-50 p-4">
290	            <p className="mb-1.5 text-[10.5px] font-semibold uppercase text-brand-700">
291	              Laba Kotor
292	            </p>
293	            <p className="text-2xl font-bold text-brand-700">{formatRupiah(grossProfit)}</p>
294	            <p className="mt-1 text-[11px] text-brand-600/80">
295	              {missingCostCount > 0
296	                ? `omzet − HPP (${missingCostCount} tx belum ada data modal)`
297	                : "omzet dikurangi HPP"}
298	            </p>
299	          </div>
300	          <div className="rounded-2xl border border-zinc-200 bg-white p-4">
301	            <p className="mb-1.5 text-[10.5px] font-semibold uppercase text-zinc-400">
302	              Margin Rata-rata
303	            </p>
304	            <p className="text-2xl font-bold text-zinc-900">
305	              {avgMargin === null ? "—" : `${avgMargin}%`}
306	            </p>
307	            <p className="mt-1 text-[11px] text-zinc-400">
308	              {avgMargin === null ? "isi harga modal produk dulu" : "laba ÷ omzet"}
309	            </p>
310	          </div>
311	        </div>
312	
313	        {/* KPI sekunder */}
314	        <div className="mt-3 grid grid-cols-3 gap-3">
315	          <div className="rounded-xl border border-zinc-200 bg-white p-3.5">
316	            <p className="mb-2 text-[10.5px] font-semibold uppercase text-zinc-400">Item Terjual</p>
317	            <p className="text-xl font-bold text-zinc-900">{totalItems}</p>
318	            <p className="mt-0.5 text-[10.5px] text-zinc-400">total qty</p>
