234	          <input
235	            type="number"
236	            name="serialFrom"
237	            min="1"
238	            defaultValue={serialFrom}
239	            className="mt-1 block w-24 rounded-lg border border-zinc-200 px-2 py-1.5 text-sm"
240	          />
241	        </label>
242	        <label className="text-xs font-medium text-zinc-600">
243	          No. Seri Sampai
244	          <input
245	            type="number"
246	            name="serialTo"
247	            min="1"
248	            defaultValue={serialTo}
249	            className="mt-1 block w-24 rounded-lg border border-zinc-200 px-2 py-1.5 text-sm"
250	          />
251	        </label>
252	        <button
253	          type="submit"
254	          className="rounded-lg bg-brand-600 px-4 py-2 text-xs font-semibold text-white hover:bg-brand-700"
255	        >
256	          Terapkan
257	        </button>
258	      </form>
259	
260	      {/* Ringkasan per kategori */}
261	      <div className="mt-4 rounded-2xl border border-zinc-200 bg-white p-4">
262	        <h2 className="text-sm font-bold text-zinc-900">Ringkasan per Kategori</h2>
263	        {categorySummary.length > 0 ? (
264	          <div className="mt-3 space-y-2">
265	            {categorySummary.map(([name, s]) => (
266	              <div key={name} className="flex items-center justify-between text-sm">
267	                <span className="font-medium text-zinc-700">
268	                  {name} <span className="text-zinc-400">({s.qty} tiket)</span>
269	                </span>
270	                <span className="font-bold text-zinc-900">{formatRupiah(s.revenue)}</span>
271	              </div>
272	            ))}
273	          </div>
274	        ) : (
275	          <p className="py-4 text-center text-xs text-zinc-300">Belum ada data</p>
276	        )}
277	      </div>
278	
279	      {/* Ekspor */}
280	      <div className="mt-4 rounded-2xl border border-zinc-200 bg-white p-4">
281	        <h2 className="mb-3 text-sm font-bold text-zinc-900">⬇️ Ekspor Data</h2>
282	        <div className="grid grid-cols-3 gap-2">
283	          <a
284	            href={`/business/${businessId}/ticket-reports/export?type=transactions&${periodQuery}`}
285	            className="flex items-center justify-center gap-1.5 rounded-xl bg-brand-600 py-2.5 text-xs font-bold text-white transition-colors hover:bg-brand-700"
