13	function addDaysStr(dateStr: string, days: number) {
14	  const d = new Date(`${dateStr}T00:00:00Z`);
15	  d.setUTCDate(d.getUTCDate() + days);
16	  return d.toISOString().slice(0, 10);
17	}
18	
19	function formatDateLabel(dateStr: string) {
20	  return new Date(`${dateStr}T00:00:00Z`).toLocaleDateString("id-ID", {
21	    weekday: "long",
22	    day: "numeric",
23	    month: "long",
24	    year: "numeric",
25	    timeZone: "UTC",
26	  });
27	}
