103	                className="text-[11px] font-medium text-brand-600 hover:underline"
104	              >
105	                Kembali ke hari ini
106	              </Link>
107	            )}
108	          </div>
109	          <Link
110	            href={`/business/${businessId}/attendance?date=${addDaysStr(date, 1)}`}
111	            className="rounded-lg px-2 py-1 text-sm text-zinc-500 hover:bg-zinc-100"
112	          >
113	            →
114	          </Link>
115	        </div>
116	
117	        <div className="mt-4 space-y-2">
118	          {cashiers && cashiers.length > 0 ? (
119	            cashiers.map((c) => (
120	              <AttendanceRow
121	                key={c.id}
122	                cashierName={c.name}
123	                currentStatus={statusByCashier.get(c.id) ?? null}
124	                action={setAttendance.bind(null, businessId, c.id, date)}
