}

function formatDate(dateStr: string) {
  return new Date(`${dateStr}T00:00:00Z`).toLocaleDateString("id-ID", {
    day: "2-digit",
    month: "short",
    year: "numeric",
    timeZone: "UTC",
  });
}

export default async function PayslipDetailPage({
  params,
}: {
  params: Promise<{ businessId: string; payslipId: string }>;
}) {
  const { businessId, payslipId } = await params;
  const supabase = await createClient();

  const { data: business } = await supabase
    .from("businesses")
    .select("name")
    .eq("id", businessId)
    .single();

  const { data: payslip } = await supabase
    .from("payslips")
    .select(
      "id, period_start, period_end, daily_rate, hadir_count, izin_count, sakit_count, alpa_count, base_pay, lembur_amount, thr_amount, created_at, paid_at, employees(name)",
    )
    .eq("id", payslipId)
    .eq("business_id", businessId)
    .single();

  if (!business || !payslip) {
    notFound();
  }

  const { data: adjustments } = await supabase
    .from("payslip_adjustments")
    .select("id, type, label, amount")
    .eq("payslip_id", payslipId)
    .order("created_at", { ascending: true });

  const cashier = payslip.cashiers as unknown as { name: string; role: string } | null;
