toolUseResult.originalFile:
"use server";

import { revalidatePath } from "next/cache";
import { createClient } from "@/lib/supabase/server";
import { logActivity } from "@/lib/activity-log";

export type AddCashierState = { error: string | null };

export async function addCashier(
  businessId: string,
  _prevState: AddCashierState,
  formData: FormData,
): Promise<AddCashierState> {
  const name = (formData.get("name") as string)?.trim();
  const role = formData.get("role") as string;
  const pin = formData.get("pin") as string;
  const confirmPin = formData.get("confirmPin") as string;
  const dailyRateRaw = formData.get("dailyRate") as string;

  if (!name) {
    return { error: "Nama kasir wajib diisi." };
  }
  if (role !== "kasir" && role !== "manajer") {
    return { error: "Pilih peran kasir dulu." };
  }
  if (!/^\d{4}$/.test(pin)) {
    return { error: "PIN harus 4 digit angka." };
  }
  if (pin !== confirmPin) {
    return { error: "PIN dan konfirmasi PIN tidak sama." };
  }
  const dailyRate = dailyRateRaw ? Number(dailyRateRaw) : 0;
  if (Number.isNaN(dailyRate) || dailyRate < 0) {
    return { error: "Gaji harian harus angka dan tidak boleh negatif." };
  }

  const supabase = await createClient();
  const { data: newCashierId, error } = await supabase.rpc("create_cashier", {
    p_business_id: businessId,
    p_name: name,
    p_role: role,
    p_pin: pin,
  });

  if (error) {
    return { error: error.message };
  }

  if (dailyRate > 0 && newCashierId) {
    await supabase
      .from("cashiers")
      .update({ daily_rate: dailyRate })
      .eq("id", newCashierId)
      .eq("business_id", businessId);
  }

  await logActivity(
    supabase,
    businessId,
    "pengaturan",
    "sukses",
    `Kasir baru: ${name}`,
    `Peran: ${role}`,
  );
  revalidatePath(`/business/${businessId}/cashiers`);
  return { error: null };
}

export type EditCashierState = { error: string | null };

export async function editCashier(
  businessId: string,
  cashierId: string,
  _prevState: EditCashierState,
  formData: FormData,
