const fs = require("fs");
const path = require("path");

const root = path.resolve(__dirname, "../../../../../../../PROJECT1/KasirKu/src");

function walk(dir, out) {
  for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
    const full = path.join(dir, entry.name);
    if (entry.isDirectory()) {
      if (entry.name === "node_modules") continue;
      walk(full, out);
    } else if (entry.name.endsWith(".tsx") || entry.name.endsWith(".ts")) {
      out.push(full);
    }
  }
}

const files = [];
walk(root, files);

const TARGET = "rounded-2xl border border-zinc-200 bg-white";
const REPLACEMENT = "rounded-xl bg-white shadow-sm";

let changedFiles = 0;
let changedCount = 0;

for (const file of files) {
  const content = fs.readFileSync(file, "utf8");
  if (!content.includes(TARGET)) continue;

  const count = content.split(TARGET).length - 1;
  let next = content.split(TARGET).join(REPLACEMENT);

  // Collapse duplicate "shadow-sm" tokens that end up in the same className
  // string (a few cards already had shadow-sm manually before this pass).
  next = next.replace(/className="([^"]*)"/g, (full, cls) => {
    const tokens = cls.split(/\s+/).filter(Boolean);
    const seen = new Set();
    const deduped = [];
    for (const t of tokens) {
      if (t === "shadow-sm") {
        if (seen.has("shadow-sm")) continue;
        seen.add("shadow-sm");
      }
      deduped.push(t);
    }
    return `className="${deduped.join(" ")}"`;
  });

  fs.writeFileSync(file, next, "utf8");
  changedFiles++;
  changedCount += count;
  console.log(`${count}\t${path.relative(root, file)}`);
}

console.log(`\nTotal: ${changedCount} occurrences across ${changedFiles} files`);

