92	                amount: number;
93	              }[];
94	              const tunjangan = adjustments
95	                .filter((a) => a.type === "tunjangan")
96	                .reduce((s, a) => s + Number(a.amount), 0);
97	              const potongan = adjustments
98	                .filter((a) => a.type === "potongan")
99	                .reduce((s, a) => s + Number(a.amount), 0);
100	              const total =
101	                Number(p.base_pay) + Number(p.lembur_amount) + Number(p.thr_amount) + tunjangan - potongan;
