110	                >
111	                  <div className="flex items-center justify-between gap-2">
112	                    <p className="truncate text-sm font-medium text-zinc-900">{employeeName}</p>
113	                    <div className="flex shrink-0 items-center gap-2">
114	                      <span className="text-sm font-semibold text-zinc-900">
115	                        {formatRupiah(total)}
116	                      </span>
