29	export default async function AttendancePage({
30	  params,
31	  searchParams,
32	}: {
33	  params: Promise<{ businessId: string }>;
34	  searchParams: Promise<{ date?: string }>;
35	}) {
36	  const { businessId } = await params;
37	  const { date: dateParam } = await searchParams;
38	  const date = dateParam && /^\d{4}-\d{2}-\d{2}$/.test(dateParam) ? dateParam : todayStr();
39	
40	  const supabase = await createClient();
41	
42	  const { data: business } = await supabase
43	    .from("businesses")
44	    .select("id, name")
45	    .eq("id", businessId)
46	    .single();
47	
48	  if (!business) {
49	    notFound();
50	  }
51	
52	  const { data: employees } = await supabase
53	    .from("employees")
54	    .select("id, name")
55	    .eq("business_id", businessId)
56	    .eq("active", true)
57	    .order("created_at", { ascending: true });
58	
59	  const { data: attendanceRows } = await supabase
60	    .from("attendance")
61	    .select("employee_id, status")
62	    .eq("business_id", businessId)
63	    .eq("date", date);
64	
65	  const statusByEmployee = new Map(
66	    (attendanceRows ?? []).map((r) => [r.employee_id, r.status as AttendanceStatus]),
67	  );
68	
69	  // ── Rekap bulan berjalan (berdasarkan tanggal yang sedang dilihat) ──
70	  const monthStart = `${date.slice(0, 7)}-01`;
71	  const { data: monthRows } = await supabase
72	    .from("attendance")
73	    .select("employee_id, status")
74	    .eq("business_id", businessId)
75	    .gte("date", monthStart)
76	    .lte("date", date);
77	
78	  const recap = new Map<string, Record<AttendanceStatus, number>>();
79	  for (const e of employees ?? []) {
80	    recap.set(e.id, { hadir: 0, izin: 0, sakit: 0, alpa: 0 });
81	  }
82	  for (const r of monthRows ?? []) {
83	    const entry = recap.get(r.employee_id);
84	    if (entry) entry[r.status as AttendanceStatus] += 1;
85	  }
86	
87	  return (
88	    <div className="w-full max-w-2xl">
89	        <h1 className="text-lg font-bold text-zinc-900">Absensi — {business.name}</h1>
90	
91	        <div className="mt-4 flex items-center justify-between rounded-xl border border-zinc-200 bg-white px-3 py-2.5">
92	          <Link
93	            href={`/business/${businessId}/attendance?date=${addDaysStr(date, -1)}`}
94	            className="rounded-lg px-2 py-1 text-sm text-zinc-500 hover:bg-zinc-100"
95	          >
96	            ←
97	          </Link>
98	          <div className="text-center">
99	            <p className="text-xs font-semibold text-zinc-900">{formatDateLabel(date)}</p>
100	            {date !== todayStr() && (
101	              <Link
102	                href={`/business/${businessId}/attendance`}
103	                className="text-[11px] font-medium text-brand-600 hover:underline"
104	              >
105	                Kembali ke hari ini
106	              </Link>
107	            )}
108	          </div>
109	          <Link
110	            href={`/business/${businessId}/attendance?date=${addDaysStr(date, 1)}`}
111	            className="rounded-lg px-2 py-1 text-sm text-zinc-500 hover:bg-zinc-100"
112	          >
113	            →
114	          </Link>
115	        </div>
116	
117	        <div className="mt-4 space-y-2">
118	          {employees && employees.length > 0 ? (
119	            employees.map((e) => (
120	              <AttendanceRow
121	                key={e.id}
122	                employeeName={e.name}
123	                currentStatus={statusByEmployee.get(e.id) ?? null}
124	                action={setAttendance.bind(null, businessId, e.id, date)}
125	              />
126	            ))
127	          ) : (
128	            <p className="rounded-xl border border-dashed border-zinc-200 px-4 py-6 text-center text-xs text-zinc-400">
129	              Belum ada karyawan aktif. Tambahkan dulu di halaman Karyawan.
130	            </p>
131	          )}
132	        </div>
133	
134	        {employees && employees.length > 0 && (
135	          <div className="mt-6 overflow-hidden rounded-xl bg-white shadow-sm">
136	            <div className="border-b border-zinc-100 px-4 py-3">
137	              <h2 className="text-sm font-bold text-zinc-900">Rekap Bulan Ini</h2>
138	              <p className="mt-0.5 text-[11px] text-zinc-400">
139	                {monthStart.slice(0, 7)} sampai {date}
140	              </p>
141	            </div>
142	            <div className="divide-y divide-zinc-100">
143	              {employees.map((e) => {
144	                const r = recap.get(e.id)!;
145	                return (
146	                  <div key={e.id} className="flex items-center justify-between px-4 py-2.5">
147	                    <span className="text-xs font-medium text-zinc-700">{e.name}</span>
148	                    <span className="text-[11px] text-zinc-500">
149	                      <span className="text-brand-700">{r.hadir} hadir</span> ·{" "}
150	                      <span className="text-amber-600">{r.izin} izin</span> ·{" "}
151	                      <span className="text-blue-600">{r.sakit} sakit</span> ·{" "}
152	                      <span className="text-red-600">{r.alpa} alpa</span>
153	                    </span>
154	                  </div>
155	                );
156	              })}
157	            </div>
158	          </div>
